import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String text = br.readLine().trim();
        int k = Integer.parseInt(br.readLine().trim());
        String[] patterns = new String[k];
        int totalLen = 1;
        for (int i = 0; i < k; i++) {
            patterns[i] = br.readLine().trim();
            totalLen += patterns[i].length();
        }
        int[] child = new int[totalLen * 26];
        Arrays.fill(child, -1);
        long[] total = new long[totalLen];
        int nodes = 1;
        for (String pat : patterns) {
            int v = 0;
            for (int i = 0; i < pat.length(); i++) {
                int c = pat.charAt(i) - 'a';
                if (child[v * 26 + c] == -1) child[v * 26 + c] = nodes++;
                v = child[v * 26 + c];
            }
            total[v]++;
        }
        int[] fail = new int[nodes];
        int[] queue = new int[nodes];
        int head = 0, tail = 0;
        for (int c = 0; c < 26; c++) {
            int u = child[c];
            if (u == -1) child[c] = 0;
            else { fail[u] = 0; queue[tail++] = u; }
        }
        while (head < tail) {
            int v = queue[head++];
            total[v] += total[fail[v]];
            for (int c = 0; c < 26; c++) {
                int u = child[v * 26 + c];
                if (u == -1) child[v * 26 + c] = child[fail[v] * 26 + c];
                else { fail[u] = child[fail[v] * 26 + c]; queue[tail++] = u; }
            }
        }
        int state = 0;
        long answer = 0;
        for (int i = 0; i < text.length(); i++) {
            state = child[state * 26 + (text.charAt(i) - 'a')];
            answer += total[state];
        }
        System.out.println(answer);
    }
}

