#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    string text;
    int k;
    cin >> text >> k;
    vector<string> patterns(k);
    int total_len = 1;
    for (auto& p : patterns) { cin >> p; total_len += p.size(); }
    vector<array<int, 26>> child(1);
    child[0].fill(-1);
    vector<ll> total(1, 0);
    for (const string& pat : patterns) {
        int v = 0;
        for (char ch : pat) {
            int c = ch - 'a';
            if (child[v][c] == -1) {
                child[v][c] = child.size();
                child.emplace_back();
                child.back().fill(-1);
                total.push_back(0);
            }
            v = child[v][c];
        }
        total[v]++;
    }
    int n = child.size();
    vector<int> fail(n, 0);
    queue<int> q;
    for (int c = 0; c < 26; c++) {
        int u = child[0][c];
        if (u == -1) child[0][c] = 0;
        else { fail[u] = 0; q.push(u); }
    }
    while (!q.empty()) {
        int v = q.front(); q.pop();
        total[v] += total[fail[v]];
        for (int c = 0; c < 26; c++) {
            int u = child[v][c];
            if (u == -1) child[v][c] = child[fail[v]][c];
            else { fail[u] = child[fail[v]][c]; q.push(u); }
        }
    }
    int state = 0;
    ll answer = 0;
    for (char ch : text) {
        state = child[state][ch - 'a'];
        answer += total[state];
    }
    printf("%lld\n", answer);
    return 0;
}
